@use "sass:map";
@use "../abstract" as *;

$theme-colors: theme-colors-flat($theme-colors-dark);

// =============================================================================
// :root — CSS Custom Properties
// =============================================================================
:root {
  // ---------------------------------------------------------------------------
  // Typography
  // ---------------------------------------------------------------------------
  --base-font-size: #{fluid(12, 16)};
  --base-line-height: 1.618;
  --base-letter-spacing: #{fluid(-0.3, -0.5)};

  @each $key, $val in $font-familys {
    --family-#{'#{$key}'}: #{$val}, sans-serif;
  }

  --font-button-link: var(--family-ui);

  // ---------------------------------------------------------------------------
  // Layout
  // ---------------------------------------------------------------------------
  --header-height: #{fluid(64, 80)};
  --hud-unit: #{fluid(164, 200)};
  --scene-shell-span: 100vh;

  @each $key, $val in $gutters {
    --gutter-#{$key}: #{fluid(map.get($val, min), map.get($val, max))};
  }
  --gutter-container: #{fluid(24, 32)};
  // ---------------------------------------------------------------------------
  // Z-index (ascending order)
  // 전역 커스텀 커서는 항상 최상단(헤더/드로어/모달 위).
  // ---------------------------------------------------------------------------
  --z-index-bg: -1;
  --z-index-sub-visual-bg: 1;
  --z-index-sub-visual-txt: 2;
  --z-index-canvas-overlay: 2;
  --z-index-backdrop: 10;
  --z-index-drawer: 270;
  --z-index-header: 280;
  --z-index-search: 280;
  --z-index-sticky-filter: 220;
  --z-index-works-canvas: 250;
  --z-index-works-cursor-ring: 251;
  --z-index-works-cursor: 253;
  --z-index-works-hud: 260;
  --z-index-modal: 300;
  --z-index-floating-button: 999;
  --z-index-go-to-top: 999;
  --z-index-dropdown: 1000;
  --z-index-dropdown-panel: 1001;
  --z-index-intro: 10000;
  --z-index-breadcrumb: 100000;
  --z-index-button-floating: 1000000;
  /* 전역 커서: 사이트 전체에서 헤더/드로어 위에 표시 (범용) */
  --z-index-custom-cursor-outline: 2147483646;
  --z-index-custom-cursor: 2147483647;
  // ---------------------------------------------------------------------------
  // Form
  // ---------------------------------------------------------------------------
  --input-height: #{fluid(40, 54)};
  --inpt-height: var(--input-height);
  --form-file-action-size: #{fluid(24, 28)};
  --form-placeholder-opacity: 0.72;
  --form-focus-ring-width: 2px;
  --form-control-transition:
    border-color var(--duration-default) var(--ease-smooth),
    background-color var(--duration-default) var(--ease-smooth),
    color var(--duration-default) var(--ease-smooth);
  --form-control-shadow-transition: box-shadow var(--duration-default)
    var(--ease-smooth);
  --form-control-surface: var(--clr-trigger-ghost);
  --form-control-surface-active: var(--clr-background-default);
  --form-control-surface-hover: color-mix(
    in srgb,
    var(--clr-white-100) 4%,
    var(--clr-trigger-ghost)
  );
  --form-control-surface-press: color-mix(
    in srgb,
    var(--clr-white-100) 7%,
    var(--clr-background-default)
  );
  --form-control-border-hover: color-mix(
    in srgb,
    var(--clr-white-100) 12%,
    var(--clr-border-default)
  );
  --form-control-shadow-base: inset 0 1px 0 rgba(255, 255, 255, 0.03);
  --form-control-shadow-hover: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  --form-control-shadow-focus:
    0 0 0 1px color-mix(in srgb, var(--clr-white-100) 8%, transparent),
    0 0 0 4px color-mix(in srgb, var(--clr-white-100) 6%, transparent);
  --form-choice-surface: rgba(255, 255, 255, 0.06);
  --form-choice-surface-hover: rgba(255, 255, 255, 0.1);
  --form-choice-surface-active: rgba(255, 255, 255, 0.14);
  --form-choice-surface-press: rgba(255, 255, 255, 0.18);
  --form-choice-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
  --form-choice-shadow-hover:
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 0 0 1px color-mix(in srgb, var(--clr-white-100) 6%, transparent);
  --form-choice-shadow-active:
    inset 0 1px 0 rgba(255, 255, 255, 0.14),
    inset 0 0 0 1px color-mix(in srgb, var(--clr-white-100) 10%, transparent);
  --form-choice-shadow-press:
    inset 0 1px 0 rgba(255, 255, 255, 0.18),
    inset 0 0 0 1px color-mix(in srgb, var(--clr-white-100) 14%, transparent);
  --form-choice-shadow-focus:
    var(--form-choice-shadow-active),
    0 0 0 4px color-mix(in srgb, var(--clr-white-100) 6%, transparent);

  // ---------------------------------------------------------------------------
  // Duration
  // ---------------------------------------------------------------------------
  --duration-instant: 0.1s;
  --duration-fast: 0.2s;
  --duration-default: 0.4s;
  --duration-slow: 0.6s;
  --duration-slower: 1s;
  --duration-stagger: 0.08s;

  // ---------------------------------------------------------------------------
  // Delay (reveal stagger 등)
  // ---------------------------------------------------------------------------
  --delay-reveal-initial: 0.04s;
  --delay-reveal-step: 0.06s;

  // ---------------------------------------------------------------------------
  // Easing — Apple HIG inspired
  // ---------------------------------------------------------------------------
  --ease-default: cubic-bezier(0.25, 0.1, 0.25, 1);
  --ease-in: cubic-bezier(0.42, 0, 1, 1);
  --ease-out: cubic-bezier(0, 0, 0.58, 1);
  --ease-in-out: cubic-bezier(0.42, 0, 0.58, 1);
  --ease-spring: cubic-bezier(0.175, 0.885, 0.32, 1.275);
  --ease-snappy: cubic-bezier(0.2, 0, 0, 1);
  --ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);

  // ---------------------------------------------------------------------------
  // Transition shorthands (duration + easing)
  // ---------------------------------------------------------------------------
  --transition-fast: var(--duration-fast) var(--ease-snappy);
  --transition-base: var(--duration-default) var(--ease-default);
  --transition-default: var(--duration-default) var(--ease-default);
  --transition-slow: var(--duration-slow) var(--ease-smooth);

  // ---------------------------------------------------------------------------
  // Reveal motion
  // ---------------------------------------------------------------------------
  --block-reveal-offset-y: 18px;
  --block-reveal-blur: 8px;
  --text-reveal-offset-y: 4px;
  --text-reveal-blur: 8px;
  --text-reveal-down-offset-y: 18px;
  --text-reveal-down-blur: 4px;

  // ---------------------------------------------------------------------------
  // Shadow
  // ---------------------------------------------------------------------------
  --shadow-floating-card:
    0 2px 5px -1px rgba(50, 50, 93, 0.25), 0 1px 3px -1px rgba(0, 0, 0, 0.3);
  --shadow-scroll-top: 0 4px 12px rgba(0, 0, 0, 0.15);

  // ---------------------------------------------------------------------------
  // Scrollbar
  // ---------------------------------------------------------------------------
  --scrollbar-width: #{fluid(6, 8)};
  --scrollbar-radius: 4px;
  --backdrop-bg: var(--clr-background-overlay);
  --backdrop-blur: 24px;
  --backdrop-duration: 0s;
  --backdrop-delay: 0ms;
  --backdrop-ease: cubic-bezier(0.4, 0, 0.6, 1);
  --modal-viewport-offset: #{fluid(20, 32)};
  --modal-enter-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --corner-bracket-size-sm: 8px;
  --corner-bracket-size-lg: 16px;
  --modal-close-corner-size: var(--corner-bracket-size-sm);
  --corner-bracket-size: var(--corner-bracket-size-lg);
  --corner-stroke-width: 4;
  --corner-glow-blur: 8px;
  --corner-glow-spread: 18px;
  --shiny-cta-bg: #000000;
  --shiny-cta-bg-subtle: #1a1818;
  --shiny-cta-fg: #ffffff;
  --shiny-cta-highlight: blue;
  --shiny-cta-highlight-subtle: #8484ff;

  // ---------------------------------------------------------------------------
  // Intro (glitch 텍스트 — color/heading은 공용 토큰 사용)
  // ---------------------------------------------------------------------------
  --intro-char-blur: 10px;
  --intro-glitch-font: #{fluid(32, 64)};
  --intro-glitch-letter-spacing-initial: 1.4em;
  --intro-glitch-font-weight: 600;

  // ---------------------------------------------------------------------------
  // Colors (auto-generated from $theme-colors)
  // ---------------------------------------------------------------------------
  @each $key, $val in $theme-colors {
    --clr-#{'#{$key}'}: #{$val};
  }
}

// =============================================================================
// Theme override — Light
// =============================================================================
html[data-theme="light"] {
  $theme-colors: theme-colors-flat($theme-colors-light);

  @each $key, $val in $theme-colors {
    --clr-#{'#{$key}'}: #{$val};
  }
}

// =============================================================================
// Utility classes
// =============================================================================

// — Color utilities (.clr-*, .bdr-*, .bg-*) —
@each $key, $val in $theme-colors {
  .clr-#{"#{$key}"} {
    color: var(--clr-#{"#{$key}"});
  }
  .bdr-#{"#{$key}"} {
    border-color: var(--clr-#{"#{$key}"});
  }
  .bg-#{"#{$key}"} {
    background: var(--clr-#{"#{$key}"});
  }
}

// — Font family utilities —
@each $key, $val in $font-familys {
  .no-family-#{"#{$key}"} {
    font-family: "#{$val}", sans-serif;
  }
}

// — Container utilities —
@each $key, $val in $containers {
  .no-container-#{"#{$key}"} {
    width: 100%;
    max-width: #{$val}px;
    margin-left: auto;
    margin-right: auto;
    padding-left: var(--gutter-container);
    padding-right: var(--gutter-container);
  }
}

.no-container {
  width: 100%;
  margin: 0 auto;
  position: relative;
  padding-left: var(--gutter-container);
  padding-right: var(--gutter-container);
}

// — Section utilities —
@each $key, $val in $sections {
  .no-section-#{"#{$key}"} {
    @include section-fluid-by-map($val);
  }
}

// — Fluid custom utilities —
@each $key, $val in $fluid-customs {
  .#{"#{$key}"} {
    @include set-fluid($val);
  }
}

// — Fluid typography utilities —
@each $type, $map in $fluid-typography {
  @each $key, $val in $map {
    .f-#{$type}-#{$key} {
      @include fs-fluid-by-map($val);
    }
  }
}

// =============================================================================
// Components
// =============================================================================

// — Scrollbar —
html {
  scrollbar-width: thin;
  scrollbar-color: var(--clr-white-24) transparent;
}

html::-webkit-scrollbar {
  width: var(--scrollbar-width);
  height: var(--scrollbar-width);
}

html::-webkit-scrollbar-track {
  background: transparent;
  border-radius: var(--scrollbar-radius);
}

html::-webkit-scrollbar-thumb {
  background: var(--clr-white-24);
  border-radius: var(--scrollbar-radius);
  transition: background var(--transition-fast);
}

html::-webkit-scrollbar-thumb:hover {
  background: var(--clr-white-40);
}

.no-scrollbar {
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb-color, var(--clr-white-24)) transparent;

  &::-webkit-scrollbar {
    width: var(--scrollbar-width-custom, var(--scrollbar-width));
    height: var(--scrollbar-width-custom, var(--scrollbar-width));
  }

  &::-webkit-scrollbar-track {
    background: var(--scrollbar-track-color, transparent);
    border-radius: var(--scrollbar-radius-custom, var(--scrollbar-radius));
  }

  &::-webkit-scrollbar-thumb {
    background: var(--scrollbar-thumb-color, var(--clr-white-24));
    border-radius: var(--scrollbar-radius-custom, var(--scrollbar-radius));
    transition: background var(--transition-fast);

    &:hover {
      background: var(--scrollbar-thumb-hover-color, var(--clr-white-40));
    }
  }
}

