      flex-direction: column;
      gap: var(--gutter-md);
    }

    &__desc {
      max-width: fluid(520, 820);
    }

    &__body {
      width: 100%;
      background: rgba(0, 0, 0, 0.24);
      backdrop-filter: blur(24px);
      -webkit-backdrop-filter: blur(24px);
    }

    &__list {
      display: flex;
      flex-direction: column;
    }

    &__item {
      display: grid;
      grid-template-columns: 2fr 6fr 4fr;
      gap: var(--gutter-sm);
      align-items: center;
      padding: var(--gutter-2xl) 0;
      border-top: 1px solid rgba(255, 255, 255, 0.12);

      &:last-child {
        border-bottom: 1px solid rgba(255, 255, 255, 0.12);
      }

      @include mq(md) {
        grid-template-columns: 1fr;
        gap: var(--gutter-xs);
      }
    }

    &__item-title {
    }

    &__item-meta {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-sm);
      min-width: 0;
    }

    &__item-tools {
      display: flex;
      flex-wrap: wrap;
      gap: var(--gutter-2xs);
      width: 100%;
    }

    .no-services__num {
      color: rgba(255, 255, 255, 0.56);
      display: flex;
      align-items: center;
      min-height: fluid(16, 22);

      .no-loop-filter-rect {
        gap: 0;

        span {
          width: fluid(4, 6);
          height: fluid(4, 6);
        }
      }
    }
  }

  &-portfolio {
    $root: &;
    width: 100%;

    .no-container-2xl {
      position: relative;
    }

    &__head {
      min-height: 100vh;
      width: 100%;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      padding: var(--gutter-3xl) var(--gutter-container);
      h2 {
      }
      .first-title {
      }
      .second-title {
      }
      .title-bottom {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: var(--gutter-md);
        align-items: flex-end;

        @include mq(md) {
          grid-template-columns: 1fr;
          align-items: flex-start;
        }
      }
      .desc {
        order: -1;

        @include mq(md) {
          order: 0;
        }
      }

      @include mq(md) {
        padding-top: calc(var(--header-height) + var(--gutter-2xl));
        padding-bottom: var(--gutter-2xl);
      }
    }

    &__head[data-active="true"] {
      opacity: 1;
      visibility: visible;
      pointer-events: auto;
    }
    &__gallery {
      width: 100%;
    }

    &__list {
      width: 100%;

      @include mq(md) {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: var(--gutter-xl) var(--gutter-lg);
      }

      @include mq(sm) {
        grid-template-columns: 1fr;
      }
    }

    &__item {
      width: 48%;
      display: flex;
      flex-direction: column;

      &:nth-child(even) {
        margin-left: auto;
      }
      &:nth-child(odd) {
        margin-right: auto;
      }

      /* 이미지 껍데기: 인사이트 갤러리와 동일(.no-sub-gallery-item__img-wrap) 사용 */
      .no-sub-gallery-item__img-wrap {
        position: relative;
        padding: var(--gutter-xs);
        border: 1px solid
          color-mix(in srgb, var(--clr-white-100) 14%, transparent);
        background: linear-gradient(
          180deg,
          color-mix(in srgb, var(--clr-white-100) 6%, transparent),
          color-mix(in srgb, var(--clr-black-100) 18%, transparent)
        );
        overflow: hidden;
      }

      .no-sub-gallery-item__img-inner {
        overflow: hidden;
      }

      .no-sub-gallery__corner {
        color: color-mix(in srgb, var(--clr-white-100) 72%, transparent);
      }

      .no-sub-gallery-item__img {
        img {
          transition:
            transform var(--transition-default),
            opacity 0.35s ease;
        }

        video {
          @include pos-full();
          opacity: 0;
          pointer-events: none;
          object-fit: cover;
        }

        &.is-video-active {
          img {
            opacity: 0;
          }

          video {
            opacity: 1;
            transition: opacity 0.35s ease;
          }
        }
      }

      &__content {
        margin-top: var(--gutter-md);
      }

      &-category {
        margin-top: var(--gutter-sm);
      }

      &-category-list {
        display: flex;
        flex-wrap: wrap;
        gap: 0.5rem;
      }

      a {
        display: block;
        color: inherit;
        text-decoration: none;
      }
    }

    @include mq(md) {
      &__item {
        width: 100%;

        &:nth-child(even),
        &:nth-child(odd) {
          margin-left: 0;
          margin-right: 0;
        }
      }
    }
  }

  &-portfolio-intro {
    width: 100%;
  }

  &-portfolio-gallery {
    width: 100%;
    .no-view-more {
      @include flex-center();
      margin-top: var(--gutter-2xl);
    }
  }
  &-portfolio__view-more {
    min-width: fluid(148, 188);
  }
  // 클라이언트 섹션: 리스트는 12칸 중 오른쪽 5칸, ul은 2열 그리드. 스크롤에 따라 list가 100%→-100% 이동
  &-clients {
    $root: &;
    > div {
      display: grid;
      grid-template-columns: 4fr 8fr;
      gap: var(--gutter-2xl);
      align-items: flex-start;
    }

    &__head-wrap {
      position: sticky;
      top: calc(var(--header-height) + var(--gutter-lg));
      align-self: start;
    }

    &__head {
      position: relative;
      height: fit-content;
      p {
        @include font("f-body-1");
        margin-top: var(--gutter-md);
      }
    }

    &__list {
      position: relative;
    }

    &__items {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: var(--gutter-md);
    }

    &__item {
      background: rgba(255, 255, 255, 0.04);
      padding: var(--gutter-md);
      backdrop-filter: blur(24px);
      -webkit-backdrop-filter: blur(24px);

      &.is-block-reveal {
        transition-delay: 0s;
      }

      a {
        display: block;
      }
      img {
        display: block;
      }
    }

    @for $i from 1 through 22 {
      &__item:nth-child(#{$i}).is-block-reveal {
        transition-delay: #{($i - 1) * 45}ms;
      }
    }

    @include mq(md) {
      > div {
        grid-template-columns: 1fr;
      }

      &__head-wrap {
        position: relative;
        top: auto;
      }

      &__items {
        gap: var(--gutter-sm);
      }
    }
  }
  &-contact {
    $root: &;
    position: relative;
    height: auto;
    min-height: var(--scene-shell-span);

    .line {
      text-align: center;
    }

    &__stage {
      position: sticky;
      top: 0;
      z-index: 4;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: var(--gutter-lg);
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      text-align: center;
      transition:
        opacity var(--transition-default),
        transform var(--transition-default);
      transform: translate3d(0, 24px, 0);
    }

    &__stage > .no-container {
      width: 100%;
    }

    &__panel {
      width: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      pointer-events: auto;
    }

    &[data-active="true"] {
      #{$root}__stage {
        opacity: 1;
        visibility: visible;
        transform: translate3d(0, 0, 0);
      }
    }

    &__head {
      width: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: var(--gutter-md);

      .line {
        text-align: center;
      }
      h2 {
        color: var(--clr-text-title);
      }
      p {
      }
    }

    &__actions {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: var(--gutter-sm);
      margin-top: var(--gutter-xl);
    }

    &__action {
      margin-top: 0;
    }

    &__footer {
      position: relative;
      z-index: 1;
      margin-top: 0;
    }

    @include mq(md) {
      &__stage {
        padding-left: var(--gutter-lg);
        padding-right: var(--gutter-lg);
      }

      &__actions {
        flex-direction: column;
        width: 100%;
      }

      &__action {
        width: 100%;
      }
    }

    @include mq(sm) {
      &__actions {
        align-items: stretch;
      }

      &__action {
        width: 100%;
      }
    }
  }

  // 메인 푸터: 왼쪽 상단 로고 / 오른쪽 상단 메뉴(소메뉴) / 왼쪽 하단 정보 / 오른쪽 하단 Contact
  &-footer {
    color: var(--clr-text-title);
    border-top: 1px solid var(--clr-border-default);
    padding: fluid(48, 80) 0;
    transition: opacity var(--transition-default);
    display: flex;
    align-items: flex-end;
    * {
      color: inherit;
    }

    .no-container-2xl {
      padding-left: var(--gutter-lg);
      padding-right: var(--gutter-lg);
    }

    &__inner {
      width: 100%;
    }

    &__top {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      padding-bottom: fluid(32, 48);
      border-bottom: 1px solid var(--clr-border-default);
      gap: var(--gutter-lg);
      @include mq(md) {
        flex-direction: column;
        align-items: flex-start;
      }

      @include mq(sm) {
        gap: var(--gutter-md);
      }
    }

    &__logo {
      a {
        display: block;
        text-decoration: none;
      }
      img {
        width: fluid(120, 160);
        height: auto;
        object-fit: contain;
      }
    }

    &__nav {
      flex-shrink: 0;
    }

    &__menu {
      display: flex;
      flex-wrap: wrap;
      gap: var(--gutter-xl) var(--gutter-2xl);
      @include mq(md) {
        flex-direction: column;
        gap: var(--gutter-md);
      }

      @include mq(sm) {
        width: 100%;
      }
    }

    &__menu-item {
      &--has-sub {
        display: flex;
        flex-direction: column;
        gap: var(--gutter-xs);
      }
    }

    &__menu-link {
      @include font("f-heading-4");
      font-weight: 600;
      color: var(--clr-text-title);
      text-decoration: none;
      transition: color var(--transition-default);
      &:hover {
        color: var(--clr-trigger-link);
      }
    }

    &__sub {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-2xs);
    }

    &__sub-link {
      @include font("f-body-2");
      font-weight: 400;
      color: var(--clr-text-body);
      text-decoration: none;
      transition: color var(--transition-default);
      &:hover {
        color: var(--clr-text-title);
      }
    }

    &__bottom {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      gap: var(--gutter-xl);
      padding-top: fluid(32, 48);
      @include mq(md) {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--gutter-lg);
      }

      @include mq(sm) {
        gap: var(--gutter-md);
      }
    }

    &__info {
      display: flex;
      flex-wrap: wrap;
      gap: var(--gutter-lg) var(--gutter-2xl);
      @include mq(md) {
        flex-direction: column;
        gap: var(--gutter-md);
      }

      @include mq(sm) {
        width: 100%;
      }
    }

    &__info-block {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-2xs);
    }

    &__info-title {
      @include font("f-body-2");
      font-weight: 600;
      color: var(--clr-text-desc);
      letter-spacing: 0.02em;
    }

    &__info-text {
      @include font("f-body-2");
      font-weight: 400;
      color: var(--clr-text-body);
    }

    &__info-link {
      color: inherit;
      text-decoration: none;
      transition: color var(--transition-default);
      &:hover {
        color: var(--clr-trigger-link);
      }
    }

    &__contact {
      flex-shrink: 0;
    }

    &__contact-link {
      @include font("f-heading-4");
      font-weight: 600;
      color: var(--clr-text-title);
      text-decoration: none;
      transition: color var(--transition-default);
      &:hover {
        color: var(--clr-trigger-link);
      }
    }
  }
}

