.no-sub-award-video-preview {
  position: fixed;
  top: 0;
  right: fluid(24, 56);
  transform: translateY(-50%);
  width: fluid(280, 480);
  aspect-ratio: 16 / 9;
  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  clip-path: inset(50% 0 50% 0);
  transition:
    opacity 0.4s cubic-bezier(0.76, 0, 0.24, 1),
    visibility 0.4s cubic-bezier(0.76, 0, 0.24, 1),
    clip-path 0.48s cubic-bezier(0.76, 0, 0.24, 1),
    top 0.44s cubic-bezier(0.76, 0, 0.24, 1);
  z-index: 100;

  &.is-visible {
    opacity: 1;
    visibility: visible;
    clip-path: inset(0% 0 0% 0);
  }

  &.is-visible.is-switching {
    clip-path: inset(50% 0 50% 0);
  }

  &.is-closing {
    opacity: 0;
    clip-path: inset(50% 0 50% 0);
  }

  video,
  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }

  @include mq(md) {
    display: none;
  }
}

.no-sub-contact {
  position: relative;
  z-index: var(--z-index-canvas-overlay);
  padding-top: var(--header-height);
  height: 100vh;
  height: 100dvh;
  display: flex;
  flex-direction: column;

  .no-container-xl {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;

    > form {
      flex: 1;
      display: flex;
      flex-direction: column;
      min-height: 0;
    }
  }
}

.no-contact-flow {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;

  &__stage {
    position: relative;
    display: grid;
    flex: 1;
    min-height: 0;
  }

  &__form-shell,
  &__success {
    position: relative;
    grid-area: 1 / 1;
    min-height: 0;
    transition:
      opacity var(--transition-slow),
      transform var(--transition-slow),
      visibility 0s linear var(--transition-slow);
  }

  &__form-shell {
    display: flex;
    flex-direction: column;
    z-index: 1;
    opacity: 1;
    visibility: visible;
    transform: translate3d(0, 0, 0);
  }

  &__success {
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 0;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transform: translate3d(0, 24px, 0);
  }
  &__success-inner {
    @include flex-center();
    flex-direction: column;
  }

  &__title {
    margin-top: 0;
  }

  &__description {
    margin-top: var(--gutter-sm);
    color: var(--clr-text-body);
    max-width: 40ch;
  }

  &__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--gutter-xs);
    margin-top: var(--gutter-lg);
  }

  &__action {
    min-width: fluid(136, 164);
    gap: fluid(8, 12);

    .no-corner-btn__text {
      display: inline-flex;
      align-items: center;
    }

    .no-corner-btn__icon {
      margin-left: fluid(10, 14);
    }
  }

  &__action-rect {
    gap: 0;
    margin-right: fluid(8, 10);
    opacity: 0;
    transform: scale(0.84);
    transition:
      opacity var(--transition-default),
      transform var(--transition-default);

    span {
      width: fluid(4, 6);
      height: fluid(4, 6);
    }
  }

  &__action:hover &__action-rect,
  &__action:focus-visible &__action-rect {
    opacity: 1;
    transform: scale(1);
  }

  &__feedback {
    margin-top: var(--gutter-sm);
    color: var(--clr-text-error);
  }
}

html[data-contact-dom-state="leaving"] {
  .no-contact-flow__form-shell {
    opacity: 1;
    visibility: visible;
    pointer-events: none;
    transform: translate3d(0, 0, 0);
    transition: none;
  }
}

html[data-contact-dom-state="success"] {
  .no-contact-flow__form-shell {
    z-index: 0;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transform: translate3d(0, 24px, 0);
  }

  .no-contact-flow__success {
    z-index: 1;
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: translate3d(0, 0, 0);
    transition-delay: 0s;
  }
}

.no-sub-works {
  $root: &;
  margin-top: var(--header-height);
  padding-top: fluid(64, 128);

  &__gallery {
    padding-right: var(--gutter-lg);
    &-list {
      position: relative;
    }
    &-item {
      width: 48%;
      display: flex;
      flex-direction: column;
      &:nth-child(even) {
        margin-left: auto;
        margin-top: -24rem;
      }
      &:nth-child(odd) {
        margin-right: auto;
      }
      & > .no-works-canvas__grid-link {
        margin-top: var(--gutter-sm);
        align-self: flex-start;
      }
      &__img {
        @include img-auto-cover(62.5%);

        img,
        video {
          @include img-cover;
          transition: transform var(--transition-default);
        }

        img {
          transition:
            transform var(--transition-default),
            opacity 0.35s ease;
        }

        video {
          @include pos-full();
          opacity: 0;
          pointer-events: none;
        }

        &.is-video-active {
          img {
            opacity: 0;
          }
          video {
            opacity: 1;
            transition:
              transform var(--transition-default),
              opacity 0.35s ease;
          }
        }
      }

      &:not(:hover) &__img video {
        opacity: 0;
        transition: none;
      }

      &__img-wrap {
        position: relative;
        padding: var(--gutter-xs);
        border: 1px solid var(--clr-border-default);
      }

      &__corner {
        color: color-mix(in srgb, var(--clr-white-100) 72%, transparent);
      }

      &__img-inner {
        overflow: hidden;
      }

      &__link {
        display: block;
        color: inherit;
        text-decoration: none;

        &:hover {
          #{$root}__gallery-item__img-inner img,
          #{$root}__gallery-item__img-inner video {
            transform: scale(1.08);
          }
        }
      }

      &__body {
        margin-top: var(--gutter-sm);
        display: flex;
        justify-content: space-between;
      }
      &__title {
        @include font("f-heading-3");
        font-weight: 700;
      }
      &__info {
        display: flex;
        margin-top: var(--gutter-sm);
        gap: var(--gutter-xs);
      }
    }
  }
  &__gallery-mobile-filter {
    display: none;
    margin-bottom: var(--gutter-sm);
  }

  &__mobile-filter-btn {
    display: inline-flex;
    align-items: center;
    gap: var(--gutter-xs);
    padding: var(--gutter-xs) var(--gutter-sm);
    border: 1px solid var(--clr-border-default);
    background: transparent;
    color: var(--clr-text-body);
    font-family: var(--family-ui);
    @include font("f-body-2");
    cursor: pointer;
    transition:
      border-color var(--transition-fast),
      color var(--transition-fast);

    &:hover,
    &:focus-visible {
      border-color: var(--clr-text-title);
      color: var(--clr-text-title);
    }

    &__icon {
      flex-shrink: 0;
      display: block;
    }
  }

  &__inner {
    display: grid;
    grid-template-columns: 3fr 9fr;
    gap: var(--gutter-md);
  }
  &__filter {
    position: sticky;
    left: 0;
    top: calc(var(--header-height) + var(--gutter-2xl));
    height: fit-content;
    z-index: var(--z-index-sticky-filter);
  }
  /* 그리드 카테고리 필터: rect는 기본 숨김, active·hover·focus 시에만 펄스 */
  &__filter-rect {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    flex-shrink: 0;

    span {
      width: fluid(3, 5);
      height: fluid(3, 5);
      background: currentColor;
      opacity: 0;
      animation: none;
    }
  }

  &__filter-item.active #{$root}__filter-rect,
  &__filter-button:hover #{$root}__filter-rect,
  &__filter-button:focus-visible #{$root}__filter-rect {
    span {
      animation: no-loop-filter-rect-pulse 1.2s linear infinite;
    }

    span:nth-child(1) {
      animation-delay: 0s;
    }

    span:nth-child(2) {
      animation-delay: 0.18s;
    }

    span:nth-child(3) {
      animation-delay: 0.54s;
    }

    span:nth-child(4) {
      animation-delay: 0.36s;
    }
  }
  &__filter-list {
    display: flex;
    flex-direction: column;
  }
  &__filter-button {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: fluid(4, 6);
    border: 0;
    background: transparent;
    color: var(--clr-text-body);
    font-family: var(--family-ui);
    opacity: 0.56;
    transition: opacity var(--transition-fast);
    cursor: pointer;
    a,
    button {
      @include font("f-body-2");
      font-family: var(--family-ui);
    }

    &::after {
      content: ".....[View]";
      margin-left: fluid(8, 12);
      display: inline-block;
      overflow: hidden;
      max-width: 0;
      opacity: 0;
      transform: translateY(0);
      pointer-events: none;
      color: var(--clr-text-desc);
      font-family: var(--family-ui);
      @include font("f-body-3");
      white-space: nowrap;
      border-right: 1px solid transparent;
      animation: none;
    }

    &:hover,
    &:focus-visible {
      opacity: 1;
    }

    &:hover::after,
    &:focus-visible::after {
      opacity: 1;
      animation:
        no-works-type 0.42s steps(11, end) forwards,
        no-works-caret 0.8s step-end infinite;
    }
    button {
      margin-left: var(--gutter-md);
    }
  }
  &__filter-item {
    &.active {
      #{$root}__filter-button {
        color: var(--clr-text-title);
        opacity: 1;

        &::after {
          content: ".....[Now]";
          opacity: 1;
          max-width: 10ch;
          animation: none;
          border-right-color: transparent;
        }

        &:hover::after,
        &:focus-visible::after {
          animation: none;
          border-right-color: transparent;
        }
      }
    }
  }

  @include mq(md) {
    &__inner {
      grid-template-columns: 1fr;
    }

    &__filter {
      position: static;
      top: auto;
      height: auto;
      padding-bottom: var(--gutter-sm);
      border-bottom: 1px solid var(--clr-border-default);
      margin-bottom: var(--gutter-md);
    }

    &__filter-list {
      flex-direction: row;
      flex-wrap: wrap;
      gap: var(--gutter-xs);
    }

    &__filter-button {
      &::after {
        display: none;
      }

      button {
        margin-left: 0;
      }
    }

    &__gallery {
      padding-right: 0;
    }

    &__gallery-list {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: var(--gutter-md) var(--gutter-sm);
      @include mq(sm) {
        gap: var(--gutter-2xl);
      }
    }

    &__gallery-item {
      width: 100%;

      &:nth-child(even) {
        margin-left: 0;
        margin-top: 0;
      }

      &:nth-child(odd) {
        margin-right: 0;
      }
    }
  }

  @include mq(sm) {
    &__gallery-list {
      grid-template-columns: 1fr;
    }

    &__filter {
      display: none;
    }
  }
}

// Grid filter bottom sheet modal
.no-grid-filter-modal {
  position: fixed;
  inset: 0;
  z-index: var(--z-index-modal);
  pointer-events: none;
  visibility: hidden;
  opacity: 0;
  transition:
    opacity 0.3s ease,
    visibility 0.3s ease;

  &.is-open {
    pointer-events: auto;
    visibility: visible;
    opacity: 1;
  }

  &__backdrop {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.6);
  }

  &__sheet {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    display: flex;
    flex-direction: column;
    background: var(--clr-surface-weak);
    border-top: 1px solid var(--clr-border-default);
