  &__close {
    background: transparent;
    border: 0;
    color: var(--clr-text-body);
    font-size: 1.25rem;
    cursor: pointer;
    padding: var(--gutter-xs);
    line-height: 1;
    opacity: 0.7;
    transition: opacity var(--transition-fast);

    &:hover {
      opacity: 1;
    }
