    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
  }

  &__option {
    width: 100%;
    text-align: left;
    border: 0;
    color: var(--clr-text-body);
    font-family: var(--family-ui);
    padding: var(--gutter-xs) 0;
    @include font("f-body-2");
    cursor: pointer;
    opacity: 0.6;
    display: flex;
    align-items: center;
    gap: var(--gutter-xs);
    border-bottom: 1px solid transparent;
    transition:
      opacity var(--transition-fast),
      border-color var(--transition-fast),
      color var(--transition-fast);

    .no-loop-filter-rect {
      visibility: hidden;
      flex-shrink: 0;
    }

    &.is-active {
      opacity: 1;
      color: var(--clr-text-title);
      .no-loop-filter-rect {
        visibility: visible;
      }
    }

    &:hover {
      opacity: 1;
      color: var(--clr-text-title);
    }
  }
}

.no-sub-work-view {
  margin-top: var(--header-height);
  padding-top: fluid(64, 128);
  padding-bottom: fluid(64, 128);

  &__inner {
    display: flex;
    flex-direction: column;
    padding-top: var(--gutter-lg);
  }

  .no-view-more {
    margin-top: var(--gutter-lg);
    .no-corner-btn-wrap {
      align-items: center;
      justify-content: center;
    }
  }
  &__visit-bar {
    align-self: flex-start;
  }

  &__head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--gutter-md);
    padding-top: var(--gutter-lg);
    border-top: 1px solid var(--clr-border-default);
  }

  &__title {
    color: var(--clr-text-title);
    @include font("f-display-2");
    font-weight: 700;
  }

  &__award {
    display: inline-flex;
    align-items: center;
    gap: var(--gutter-xs);
    color: var(--clr-text-body);
    @include font("f-body-2");

    img {
      width: fluid(20, 36);
      height: fluid(20, 36);
      object-fit: contain;
      flex-shrink: 0;
    }

    span {
      font-family: var(--family-en-title);
      @include font("f-body-3");
    }
  }
  .no-corner-btn-wrap {
    display: flex;
    justify-content: flex-end;
    @include mq(md) {
      align-items: center;
      justify-content: center;
    }
    @include mq(sm) {
      display: block;
      width: 100%;

      .no-corner-btn {
        display: flex;
        width: 100%;
      }
    }
  }

  &__info {
    margin-top: var(--gutter-2xl);
    display: grid;
    grid-template-columns: 10fr 2fr;
    gap: var(--gutter-md);

    &-list {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: var(--gutter-sm);
    }

    &-item {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-sm);
    }

    &-label {
      color: var(--clr-text-body);
      font-family: var(--family-ui);
      @include font("f-body-3");
    }

    &-value {
      color: var(--clr-text-title);
      @include font("f-body-1");
    }

    &-sub-list {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-2xs);
    }

    &-sub-text {
      color: var(--clr-text-title);
      @include font("f-body-1");
    }

    .no-sub-work-view__button {
      align-self: flex-start;
      min-width: fluid(152, 188);
    }
  }

  &__thumbnail {
    position: relative;
    overflow: hidden;
    isolation: isolate;
    border: 1px solid var(--clr-border-default);
    padding: var(--gutter-xs);
    margin-top: var(--gutter-2xl);

    video,
    img {
      width: 100%;
      aspect-ratio: 16/9;
      display: block;
      object-fit: cover;
      position: relative;
      z-index: 1;
    }
  }

  &__content {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    background: var(--clr-surface-default);
    border: 1px solid var(--clr-border-default);

    &-wrap {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-2xl);
      @include mq(md) {
        gap: var(--gutter-lg);
      }
    }

    &__overview {
      padding: var(--gutter-xl);
      gap: var(--gutter-lg);
      display: grid;
      grid-template-columns: 3fr 9fr;
    }

    &-title {
      color: var(--clr-text-title);
      @include font("f-heading-1");
    }

    &-description {
      color: var(--clr-text-body);
      @include font("f-body-3");
    }

    &__image {
      img,
      video {
        width: 100%;
        display: block;
        object-fit: cover;
      }
    }
  }

  @include mq(lg) {
    &__info {
      grid-template-columns: 1fr;
      gap: var(--gutter-lg);
    }

    &__info-list {
      grid-template-columns: repeat(2, 1fr);
    }
  }

  @include mq(md) {
    &__head {
      flex-direction: column;
      align-items: flex-start;
      gap: var(--gutter-sm);
    }

    &__content {
      &__overview {
        grid-template-columns: 1fr;
        gap: var(--gutter-md);
      }
    }
  }

  @include mq(sm) {
    &__info-list {
      grid-template-columns: 1fr;
      gap: 0;
    }
    &__info-item {
      padding: var(--gutter-sm) 0;
      border-bottom: 1px solid var(--clr-border-default);
      gap: var(--gutter-2xs);
      &:first-child {
        padding-top: 0;
      }
    }

    &__visit-bar {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      z-index: calc(var(--z-index-header) - 80);
      display: flex;
      justify-content: center;
      padding: var(--gutter-container);
      background: color-mix(
        in srgb,
        var(--clr-surface-default) 88%,
        transparent
      );
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-top: 1px solid var(--clr-border-default);

      .no-corner-btn-wrap {
        display: block;
        width: 100%;
      }

      .no-sub-work-view__button {
        min-width: 0;
        width: 100%;
      }
    }
  }
}

@keyframes no-works-type {
  from {
    max-width: 0;
  }
  to {
    max-width: 11ch;
  }
}

@keyframes no-works-caret {
  0%,
  49% {
    border-right-color: var(--clr-text-desc);
  }
  50%,
  100% {
    border-right-color: transparent;
  }
}

content.text:
이제 최종 보고서를 작성합니다. 지금까지 수집한 정보를 정리합니다.

## 프로젝트 Responsive/Resize 로직 전수 조사 보고서

### 1. 핵심 아키텍처 개요

이 프로젝트는 **ResponsiveRuntime**을 중앙 집중식 상태 관리 시스템으로 사용하며, **ResizeSetup**이 window resize 이벤트를 리스닝하고 모든 컴포넌트에 snapshot을 배포하는 구조입니다.

---

### 2. 주요 파일별 상세 분석

#### **2.1 `/resource/ts/runtime/ResponsiveRuntime.ts` - 핵심 반응형 상태 관리**

**역할**: viewport 변경을 감지하고 전체 앱 상태를 관리하는 싱글톤

**breakpoint 판단 로직**:
```typescript
private _resolveBreakpoint(viewportWidth: number): ResponsiveBreakpoint {
  if (viewportWidth < 768) return "mobile";
  if (viewportWidth < 1024) return "tablet";
  if (viewportWidth < 1600) return "desktop";
  return "wide";
}
```
- **기준값**: 768px (mobile), 1024px (tablet), 1600px (wide)
- **기본 viewport**: 1440x900

**스케일 계산 (3가지)**:
```typescript
viewportScale: clamp(width / 1440, 0.72, 1.24)           // UI 스케일
typographyScale: clamp(width / 1600, 0.82, 1.08)        // 텍스트 스케일  
worldScale: clamp(width / 1440, 0.8, 1.12)              // Three.js 씬 스케일
```

**CSS 변수 업데이트**:
```typescript
--rvw (뷰포트 너비)
--rvh (뷰포트 높이)
--rdpr (픽셀 비율)
--r-breakpoint (현재 breakpoint)
--r-viewport-scale, --r-typography-scale, --r-world-scale
```

**matchMedia 리스닝**:
- `(prefers-reduced-motion: reduce)` - 애니메이션 감소 선호도
- `(hover: hover) and (pointer: fine)` - 호버 가능성
- `(pointer: coarse)` - 터치 포인터

**snapshot 구조**:
```typescript
{
  viewportWidth, viewportHeight, deviceType, isMobile, breakpoint,
  render: { devicePixelRatio, pixelRatioMax, clampedPixelRatio },
  flags: { reducedMotion, hoverCapable, coarsePointer },
  performance: MainPerformanceProfile,
  tokens: { viewportScale, typographyScale, worldScale }
}
```

---

#### **2.2 `/resource/ts/app/ResizeSetup.ts` - Resize 이벤트 처리**

**역할**: window/visualViewport resize를 감지하고 Engine에 반영

**핵심 로직**:
```typescript
window.addEventListener("resize", this._boundHandler);
if (window.visualViewport != null) {
  window.visualViewport.addEventListener("resize", this._visualViewportHandler);
}
```

**debounce 기본값**: 250ms (설정 가능)

**호출 체인**:
1. `resize` 이벤트 → debounce 처리
2. `ResponsiveRuntime.init()` + `updateFromWindow()`
3. 생성된 snapshot을 `engine.applyResponsiveSnapshot(snapshot)` 전달
4. scroll driver 있으면 `refresh()` 호출

**iOS 특수 처리**:
- `window.visualViewport`를 지원하면 별도 리스너 추가 (address bar 숨김/표시 대응)

---

#### **2.3 `/resource/ts/utils/Device.ts` - 디바이스 타입 판정**

**역할**: User Agent 기반 디바이스 타입 판정

**판정 로직**:
```typescript
function detectDeviceType(): DeviceType {
  if (/iPhone|iPod/i.test(UA)) return "ios";
  if (/iPad/i.test(UA)) return "ios";
  if (/Macintosh/i.test(UA) && navigator.maxTouchPoints > 1) return "ios";
  if (/Android/i.test(UA)) return "android";
  if (/Mobi|Tablet/i.test(UA)) return "android";
  return "desktop";
}

get isMobile(): boolean {
  return this._deviceType === "ios" || this._deviceType === "android";
}
```

**iOS 특수 처리**:
```typescript
resolveViewportHeight() {
  if (IS_IOS && window.visualViewport != null) {
    return window.visualViewport.height;  // address bar 고려
  }
  return window.innerHeight ?? 0;
}
```

---

#### **2.4 `/resource/ts/core/Engine.ts` - Three.js 렌더러 resize**

**초기화**:
```typescript
const aspect = responsive.viewportWidth / responsive.viewportHeight;
this._camera = new THREE.PerspectiveCamera(fov, aspect, near, far);
this._renderer.setSize?.(w, h);
this._renderer.setPixelRatio?.(Math.min(responsive.render.clampedPixelRatio, this._pixelRatioMax));
```

**Resize 흐름** (`setViewport` 메서드):
```typescript
setViewport(width: number, height: number): void {
  const dpr = Math.min(ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio, this._pixelRatioMax);

  // 1. Camera aspect 업데이트
  this._camera.aspect = width / height;
  this._camera.updateProjectionMatrix();

  // 2. Renderer 리사이즈
  this._renderer?.setPixelRatio?.(dpr);
  this._renderer?.setSize?.(width, height);

  // 3. 부가 시스템 리사이즈
  this._postProcessor?.resize(width, height, dpr);
  this._backgroundManager?.resize(width, height, dpr);
}
```

**호출 흐름**:
```
ResizeSetup.resize event
→ ResponsiveRuntime.updateFromWindow()
→ Engine.applyResponsiveSnapshot(snapshot)
→ Engine.setViewport(width, height)
```

---

#### **2.5 `/resource/ts/core/PostProcessor.ts` - 포스트 프로세싱 resize**

**역할**: Bloom & Vignette 이펙트의 render target 리사이징

```typescript
resize(width: number, height: number, pixelRatio?: number): void {
  const dpr = pixelRatio ?? ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio;

  if (this._selective) {
    this._bloomComposer?.setSize(width, height);
    this._bloomComposer?.setPixelRatio(dpr);
    this._finalComposer?.setSize(width, height);
    this._finalComposer?.setPixelRatio(dpr);
  } else {
    this._composer?.setSize(width, height);
    this._composer?.setPixelRatio(dpr);
  }

  if (this._bloomPass) {
    this._bloomPass.resolution.set(width, height);
  }
}
```

---

#### **2.6 `/resource/ts/manager/BackgroundManager.ts` - 배경 셰이더 resize**

**역할**: 셰이더 기반 배경의 render target과 uniforms 업데이트

```typescript
resize(width: number, height: number, pixelRatio = 1): void {
  const performance = this._getPerformanceProfile();
  const renderWidth = Math.round(width * pixelRatio * performance.backgroundResolutionScale);
  const renderHeight = Math.round(height * pixelRatio * performance.backgroundResolutionScale);

  // Render target 리사이징
  this._displayRenderTarget.setSize(renderWidth, renderHeight);
  this._variantRenderTarget.setSize(renderWidth, renderHeight);
  this._transitionFromRenderTarget.setSize(renderWidth, renderHeight);

  // Material uniforms 업데이트
  this._materialRuntime.resize();  // uResolution uniform 업데이트
  resolution.set(renderWidth, renderHeight, 1, 1);
}
```

**성능 기반 해상도 스케일**:
- HIGH: `backgroundResolutionScale: 1`
- MID: `backgroundResolutionScale: 0.85`
- LOW: `backgroundResolutionScale: 0.65`

---

#### **2.7 `/resource/ts/runtime/BackgroundMaterialRuntime.ts`**

**역할**: 배경 셰이더 material의 resolution uniform 관리

```typescript
resize(): void {
  const { width, height } = this._getResolution();
  this._materials.forEach((material) => {
    const resolution = material.uniforms.uResolution?.value;
    if (resolution instanceof THREE.Vector2) {
      resolution.set(width, height);
    }
  });
}
```

---

#### **2.8 `/resource/ts/utils/Device.ts` + `/resource/ts/utils/PerformanceProfile.ts` - 성능 기반 선택**

**Device 클래스**:
- `viewportWidth`, `viewportHeight` 캐싱
- `isMobile` 판정 → 모바일 최적화 설정

**PerformanceProfile**:
```typescript
// 환경 정보로 performance tier 결정
function getViewportInfo() {
  const width = window.innerWidth ?? 1440;
  const height = window.visualViewport?.height ?? window.innerHeight ?? 900;
  const isCompact = width < 768;
  return { width, height, dpr, isCompact };
}

// HIGH, MID, LOW 프로필별 설정
HIGH: pixelRatioMax 1.5, antialias true, ...
MID: pixelRatioMax 1.25, antialias false, backgroundResolutionScale 0.85
LOW: pixelRatioMax 1.0, antialias false, backgroundResolutionScale 0.65
```

---

### 3. 컴포넌트별 Responsive 대응

#### **3.1 `/resource/ts/components/CustomCursor.ts`**

```typescript
// ResponsiveRuntime 구독하여 viewport 변경 감지
// matchMedia "(pointer: coarse)" 로 터치 포인터 판정
viewportHideQuery = window.matchMedia("(max-width: 768px)");
```

#### **3.2 `/resource/ts/components/Marquee.ts`**

```typescript
// ResizeObserver + window "resize" 이벤트로 group 너비 재계산
window.addEventListener("resize", this._handleResize);
this._observeResize();  // ResizeObserver 사용

refresh(): void {
  this._groupWidth = this._elements.item.offsetWidth;
  const duration = this._groupWidth / this._speed;
  // GSAP 애니메이션 duration 재계산
}
```

#### **3.3 `/resource/ts/ui/IntroCanvas.ts`**

```typescript
// Canvas DPR 대응 resize
private _resize(): void {
  const rect = this._canvas.getBoundingClientRect();
  const dpr = ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio;
  this._canvas.width = rect.width * dpr;
  this._canvas.height = rect.height * dpr;
  this._context.scale(dpr, dpr);
}

window.addEventListener("resize", this._resize);
```

#### **3.4 `/resource/ts/runtime/SubpageStarfieldRuntime.ts`**

```typescript
// Canvas 기반 배경 애니메이션
private _bindEvents(): void {
  this._resizeListener = () => this._resize();
  window.addEventListener("resize", this._resizeListener);
}

private _resize(): void {
  this._width = window.innerWidth ?? 0;
  this._height = window.innerHeight ?? 0;
  this._canvas.width = this._width;
  this._canvas.height = this._height;
}
```

---

#### **3.5 `/resource/ts/pages/about/render/InfiniteGalleryRenderer.ts` (Works 페이지 독립 렌더러)**

**역할**: 독립적인 Three.js 렌더러 (main Engine과 별도)

```typescript
const CARD_SCALE_BASE_WIDTH = 1440;
const CARD_SCALE_MOBILE_BASE_WIDTH = 600;

// 스케일 계산
function resolveCardScale(viewportWidth: number): number {
  const baseWidth = viewportWidth < 768 ? CARD_SCALE_MOBILE_BASE_WIDTH : CARD_SCALE_BASE_WIDTH;
  return viewportWidth / baseWidth;
}
```

**주의**: Works 페이지는 자체 렌더러를 사용하므로 별도 resize 처리 필요

---

#### **3.6 `/resource/ts/pages/works/render/WorksSceneManager.ts` - Works 페이지 렌더러**

```typescript
// 독립 Three.js 렌더러
// ResponsiveRuntime 참조하여 viewport 기반 카드 배치 계산
const responsive = ResponsiveRuntime.getDefault().getSnapshot();
// viewport에 따라 scatter 위치 재계산 필요
```

---

#### **3.7 `/resource/ts/runtime/ScrollSceneRuntime.ts` - 스크롤 트리거**

```typescript
// viewport 높이로 activation offset 계산
_resolveActivationOffset(options: ScrollSceneProgressOptions): number {
  const vh = this._getViewportHeight();  // ResponsiveRuntime에서 얻음
  return vh * (activationOffsetRatio ?? 0);
}
```

---

#### **3.8 `/resource/ts/manager/ObserveManager.ts` - IntersectionObserver**

```typescript
// ResponsiveRuntime으로부터 viewport 정보 얻음
const rootMargin = "18% 0px -18% 0px";  // viewport 대비 상대값
```

---

### 4. 애니메이션/Theatre.js 관련 Responsive 처리

#### **Theatre.js와의 연결**:
- `/resource/ts/runtime/TimelineRuntime.ts` - Theatre sheet 기반 애니메이션
- `/resource/ts/runtime/AppEngineRuntime.ts` - Engine + ResponsiveRuntime 초기화
- `/resource/ts/runtime/AppStartupRuntime.ts` - 앱 부팅 시 ResizeSetup 초기화

```typescript
// AppStartupRuntime.ts
engineContext.resizeSetup.init(engine);  // resize listener 등록 및 초기 snapshot 적용
```

**Theatre.js 애니메이션은 ResponsiveSnapshot을 통해 viewport에 따른 다른 animation state 적용 가능**하지만, 현재 코드에서는 `updateFromWindow()` 시 모든 리스너에게 snapshot을 배포하므로 Theatre sheet도 자동 감지 가능

---

### 5. 성능 최적화 및 주의사항

#### **5.1 Debounce**:
- **기본값**: 250ms (ResizeSetup)
- resize 이벤트 과다 발생 방지

#### **5.2 Pixel Ratio 제한**:
```typescript
clampedPixelRatio: Math.min(devicePixelRatio, pixelRatioMax)
```
- HIGH: max 1.5
- MID: max 1.25
- LOW: max 1.0

#### **5.3 Background Resolution Scale**:
```typescript
renderWidth = width * pixelRatio * performance.backgroundResolutionScale
```
- 셰이더 기반 배경의 render target 해상도를 성능에 따라 조정

#### **5.4 visualViewport 특수 처리**:
- iOS 기기에서 address bar 숨김/표시 시 height 변경 감지
- ResizeSetup이 visualViewport.resize도 리스닝

---

### 6. 누락 및 주의사항

#### **6.1 Works 페이지 독립 렌더러**:
- `InfiniteGalleryRenderer`, `WorksSceneManager`는 main Engine과 별개
- **resize 처리가 중앙화되지 않음** → 각 렌더러가 ResponsiveRuntime 구독해야 함
- **확인 필요**: Works 페이지 렌더러가 resize 이벤트를 제대로 처리하는지

#### **6.2 Theatre.js와의 명시적 연결 부재**:
- Theatre sheet의 애니메이션이 responsive snapshot 변경 시 자동 업데이트되는지 명확하지 않음
- timeline의 `updateProjectionMatrix()` 호출 시점 확인 필요

#### **6.3 레이아웃 재계산 로직**:
- Marquee, CustomCursor 등 일부 컴포넌트는 ResizeObserver 또는 window resize로 처리
- **모든 컴포넌트가 ResponsiveRuntime 구독하지는 않음** → 불일치 가능성

#### **6.4 웹 폰트 로드 후 layout shift**:
- resize/responsive 이벤트 외에 font-load 이벤트 처리 미확인

#### **6.5 bfcache 대응**:
- `pageshow` 이벤트에서 전체 앱 재초기화 → resize setup도 재등록됨

