#### **3.2 `/resource/ts/components/Marquee.ts`**

```typescript
// ResizeObserver + window "resize" 이벤트로 group 너비 재계산
window.addEventListener("resize", this._handleResize);
this._observeResize();  // ResizeObserver 사용

refresh(): void {
  this._groupWidth = this._elements.item.offsetWidth;
  const duration = this._groupWidth / this._speed;
  // GSAP 애니메이션 duration 재계산
}
```

#### **3.3 `/resource/ts/ui/IntroCanvas.ts`**

```typescript
// Canvas DPR 대응 resize
private _resize(): void {
  const rect = this._canvas.getBoundingClientRect();
  const dpr = ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio;
  this._canvas.width = rect.width * dpr;
  this._canvas.height = rect.height * dpr;
  this._context.scale(dpr, dpr);
}

window.addEventListener("resize", this._resize);
```

#### **3.4 `/resource/ts/runtime/SubpageStarfieldRuntime.ts`**

```typescript
// Canvas 기반 배경 애니메이션
private _bindEvents(): void {
  this._resizeListener = () => this._resize();
  window.addEventListener("resize", this._resizeListener);
}

private _resize(): void {
  this._width = window.innerWidth ?? 0;
  this._height = window.innerHeight ?? 0;
  this._canvas.width = this._width;
  this._canvas.height = this._height;
}
```

